from redesign import *
e=lanes(['RendererInServer','PaRendererStreamImpl','PA 主循环','PA stream','服务状态回程'],[175,420,665,905,1130],240,590)
e+=msg(175,420,313,'Start()','navy',20)+[t(285,345,320,32,'PaLockGuard(mainloop)',20,'amber')]+msg(420,665,398,'pa_stream_cork(0)','amber',20)+msg(665,905,467,'uncork 操作','amber',20)+msg(905,420,529,'PAStreamStartSuccessCb','blue',19)+msg(420,1130,575,'OnStatusUpdate(STARTED)','blue',19)
e += [t(65,617,1145,37,'5.1 中 PA daemon 由 audio_server 内线程启动；libpulse 流与自定义 hdi_sink 同处系统链路',22,'navy',True)]
save(4,'5.1 方案：PA Start 经主循环和 cork 回调','服务端调用返回与 PA 成功回调，是两个不同位置',e,'在OpenHarmony 5.1中，AudioServer通过paDaemonThread运行ohos_pa_main，PA不是一个与鸿蒙音频底座隔离的外部黑盒。策略、RendererInServer仍在鸿蒙框架里。流实现PaRendererStreamImpl的Start持PaLockGuard保护mainloop，检查PA stream为READY，随后pa_stream_cork(stream,0,PAStreamStartSuccessCb)提交解除cork操作。Start函数成功返回只说明这一调用路径完成，状态更新在后面的PAStreamStartSuccessCb：置RUNNING并调用statusCallback的OPERATION_STARTED。\n图中的PA主循环与PA stream是逻辑参与者，不能据此断言cork在同一个回调栈中同步完成。5.1还在hdi_sink中承担混音/场景音效和HDI适配，下一页展示普通主输出真正把数据交给写线程的位置。这里对照的是控制请求进入旧执行模型的方式。PA本身包含异步消息机制，所以后文不会把旧方案概括为“所有队列都靠一把锁”。',['daemon','pastart','palock','pa','effectold'],'5.1固定版本；cork 成功回调驱动 STARTED，旧 PA 也有异步机制','泳道中的 PA 主循环/stream 为逻辑对象，非独立进程。')
